mapper.select:
SELECT c.id, c.list_price, c.relevance, c.rating, c.display_order
FROM (
    SELECT p.id, p.display_order, p.rating,
           (SELECT COALESCE(MIN(CASE WHEN i.stock > 0 THEN s.price END), MIN(s.price))
              FROM sku s JOIN inventory i ON i.sku_id = s.id
             WHERE s.product_id = p.id AND s.retired = 0) AS list_price,

               0


                       (p.search_text LIKE CONCAT('%', #{term}, '%'))


            AS relevance
    FROM product p
    WHERE p.retired = 0
    AND 1 = 0
    AND p.category = #{category}
    AND p.rating >= #{minRating}

        AND (

            p.search_text LIKE CONCAT('%', #{term}, '%')

        )

    AND EXISTS (
        SELECT 1 FROM sku s JOIN inventory i ON i.sku_id = s.id
        WHERE s.product_id = p.id AND s.retired = 0
        AND s.price >= #{minPrice}
        AND s.price <= #{maxPrice}
        AND i.stock > 0
        AND i.stock = 0

            AND s.${f.column} ${f.operator} #{f.value}


            AND (LOWER(JSON_UNQUOTE(JSON_EXTRACT(s.option_values, #{f.path}))) = #{f.value}
                 OR LOWER(JSON_UNQUOTE(JSON_EXTRACT(s.attributes, #{f.path}))) LIKE CONCAT('%', #{f.value}, '%'))

    )
) c




                c.list_price > #{cursor.price}
                OR (c.list_price = #{cursor.price} AND c.id > #{cursor.id})


                c.list_price < #{cursor.price}
                OR (c.list_price = #{cursor.price} AND c.id > #{cursor.id})


                COALESCE(c.rating, -1) < #{cursor.rating}
                OR (COALESCE(c.rating, -1) = #{cursor.rating} AND c.id > #{cursor.id})


                c.relevance < #{cursor.relevance}
                OR (c.relevance = #{cursor.relevance} AND c.display_order > #{cursor.displayOrder})
                OR (c.relevance = #{cursor.relevance} AND c.display_order = #{cursor.displayOrder}
                    AND c.id > #{cursor.id})





    ORDER BY c.list_price ASC, c.id ASC
    ORDER BY c.list_price DESC, c.id ASC
    ORDER BY COALESCE(c.rating, -1) DESC, c.id ASC
    ORDER BY c.relevance DESC, c.display_order ASC, c.id ASC

LIMIT #{fetch}
